      '$hoy = Get-ADGroupMember -Identity {{GROUP}} -Recursive | Select-Object -ExpandProperty SamAccountName; $base = Import-Csv C:\\temp\\linea-base.csv; Compare-Object -ReferenceObject $base.SamAccountName -DifferenceObject $hoy',
      "Get-WinEvent -FilterHashtable @{LogName='Security';Id=4728} -MaxEvents 50 | Format-List TimeCreated,Message",
